// El input JSON completo que llega al webhook
const webhookInput = $input.item.json;

// 1. Parsear el 'payload' que viene como un string
const payload = JSON.parse(webhookInput.body.payload);

// 2. Extraer los datos clave que necesitas
const channelId = payload.container.channel_id;
const messageTs = payload.container.message_ts;
const actionId = payload.actions[0].action_id;

// 3. Obtener los bloques del mensaje original y filtrarlos
const originalBlocks = payload.message.blocks;

// Creamos un nuevo array de bloques, excluyendo el que tiene type: "actions"
const blocksSinBotones = originalBlocks.filter(block => block.type !== 'actions');

// 4. Devolver un único objeto JSON con toda la información formateada
return {
  channel_id: channelId,
  message_ts: messageTs,
  action_id: actionId,
  // [CAMBIO CLAVE] El array ahora está dentro de un objeto con la clave "blocks"
  blocks_actualizados: {
    "blocks": blocksSinBotones
  }
};

